#include <cstddef>

// Copies src into dest (destSize bytes), always zero-terminated. Returns the characters copied.
std::size_t copyName(char* dest, std::size_t destSize, const char* src)
{
    if (destSize == 0) return 0;
    std::size_t i{ 0 };
    while (i + 1 < destSize && src[i] != '\0')
    {
        dest[i] = src[i];
        ++i;
    }
    dest[i] = '\0';
    return i;
}

unitTests:
#include <string>
TEST("fits") { char b[5]{}; CHECK_EQ(copyName(b, 5, "Rook"), std::size_t{ 4 }); CHECK_EQ(std::string(b), std::string("Rook")); }
TEST("too long is cut short and terminated") { char b[5]{}; CHECK_EQ(copyName(b, 5, "Grimbold"), std::size_t{ 4 }); CHECK_EQ(std::string(b), std::string("Grim")); }
TEST("never writes past the buffer")
{
    char b[8];
    for (char& c : b) c = '#';
    copyName(b, 4, "Longname");
    CHECK_EQ(std::string(b, 3), std::string("Lon"));
    CHECK_EQ(b[3], '\0');
    CHECK_EQ(b[4], '#');
}
TEST("an empty name") { char b[4]{ 'x', 'x', 'x', 'x' }; CHECK_EQ(copyName(b, 4, ""), std::size_t{ 0 }); CHECK_EQ(b[0], '\0'); }
TEST("a one-byte buffer holds only the terminator") { char b[1]{ 'x' }; CHECK_EQ(copyName(b, 1, "Abc"), std::size_t{ 0 }); CHECK_EQ(b[0], '\0'); }
TEST("a zero-size buffer is left alone") { char b[1]{ 'x' }; CHECK_EQ(copyName(b, 0, "Abc"), std::size_t{ 0 }); CHECK_EQ(b[0], 'x'); }

